import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadMontserrat = makeLoadFont('Montserrat');

// Load fonts at module level
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: montserratFamily } = loadMontserrat();

// Single inline schema definition


export type CostCascadeProps = Record<string, any>;

const CostCascade: React.FC<CostCascadeProps> = ({
  backgroundColor = "#FDFBF7", // Warm Ivory
  transparentBackground = false,
  durationInSeconds = 6,
  guest1 = "AUNT LISA",
  guest2 = "PARTNER",
  textColor = "#2C2C2C", // Charcoal
  accentColor = "#C5A880", // Muted Gold
  costs = [
    "CHAIRS",
    "TABLE",
    "LINEN",
    "CENTERPIECE",
    "INVITATIONS",
    "FAVORS",
    "BAR",
    "TRANSPORTATION",
    "CAPACITY",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Responsive scaling factor
  const s = Math.min(width, height) / 1080;

  // Background parsing
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants
  const leftX = width * 0.28;
  const rightX = width * 0.72;
  const centerX = width * 0.5;
  const topY = height * 0.12;
  const cardH = 100 * s;
  const cardW = 340 * s;
  
  const bracketTopY = topY + cardH / 2;
  const bracketBottomY = height * 0.18;
  const listStartY = height * 0.28;
  const listEndY = height * 0.88;

  // Timing Constants
  const f_cards = 0;
  const f_bracket = Math.floor(0.6 * fps);
  const f_stem = Math.floor(1.1 * fps);
  const stem_duration = Math.floor(3.0 * fps);

  // Card 1 Animation
  const guest1Slide = interpolate(frame, [f_cards, f_cards + 0.5 * fps], [40 * s, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });
  const guest1Opacity = interpolate(frame, [f_cards, f_cards + 0.5 * fps], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Card 2 Animation
  const f_card2 = Math.floor(0.15 * fps);
  const guest2Slide = interpolate(frame, [f_card2, f_card2 + 0.5 * fps], [40 * s, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });
  const guest2Opacity = interpolate(frame, [f_card2, f_card2 + 0.5 * fps], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Bracket Animation
  const bracketProgress = interpolate(frame, [f_bracket, f_bracket + 0.5 * fps], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });
  
  const leftBracketLength = (bracketBottomY - bracketTopY) + (centerX - leftX);
  const rightBracketLength = (bracketBottomY - bracketTopY) + (rightX - centerX);

  // Stem Animation
  const stemProgress = interpolate(frame, [f_stem, f_stem + stem_duration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const stemLength = listEndY - bracketBottomY;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Background SVG for Paths */}
      <svg style={{ position: "absolute", width, height, top: 0, left: 0, overflow: "visible" }}>
        {/* Left Bracket */}
        <path
          d={`M ${leftX} ${bracketTopY} L ${leftX} ${bracketBottomY} L ${centerX} ${bracketBottomY}`}
          fill="none"
          stroke={accentColor}
          strokeWidth={3 * s}
          strokeDasharray={leftBracketLength}
          strokeDashoffset={leftBracketLength * (1 - bracketProgress)}
          style={{ opacity: frame >= f_bracket ? 1 : 0, transition: "none" }}
        />
        
        {/* Right Bracket */}
        <path
          d={`M ${rightX} ${bracketTopY} L ${rightX} ${bracketBottomY} L ${centerX} ${bracketBottomY}`}
          fill="none"
          stroke={accentColor}
          strokeWidth={3 * s}
          strokeDasharray={rightBracketLength}
          strokeDashoffset={rightBracketLength * (1 - bracketProgress)}
          style={{ opacity: frame >= f_bracket ? 1 : 0, transition: "none" }}
        />

        {/* Central Stem */}
        <path
          d={`M ${centerX} ${bracketBottomY} L ${centerX} ${listEndY}`}
          fill="none"
          stroke={accentColor}
          strokeWidth={3 * s}
          strokeDasharray={stemLength}
          strokeDashoffset={stemLength * (1 - stemProgress)}
          style={{ opacity: frame >= f_stem ? 1 : 0, transition: "none" }}
        />

        {/* Branches and Dots */}
        {costs.map((_, i) => {
          const numItems = costs.length;
          const yStep = (listEndY - listStartY) / Math.max(1, numItems - 1);
          const itemY = listStartY + i * yStep;
          
          const progressRatio = i / Math.max(1, numItems - 1);
          const itemStemTime = f_stem + Math.floor(stem_duration * progressRatio);
          
          const isLeft = i % 2 === 0;
          const branchEndX = isLeft ? width * 0.35 : width * 0.65;
          const branchLength = Math.abs(branchEndX - centerX);
          
          const bProgress = interpolate(frame, [itemStemTime, itemStemTime + Math.floor(0.3 * fps)], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.ease),
          });
          
          const dotScale = interpolate(frame, [itemStemTime + Math.floor(0.2 * fps), itemStemTime + Math.floor(0.4 * fps)], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.back(1.5)),
          });

          return (
            <g key={`branch-path-${i}`}>
              <path
                d={`M ${centerX} ${itemY} L ${branchEndX} ${itemY}`}
                fill="none"
                stroke={accentColor}
                strokeWidth={2 * s}
                strokeDasharray={branchLength}
                strokeDashoffset={branchLength * (1 - bProgress)}
                style={{ opacity: frame >= itemStemTime ? 1 : 0, transition: "none" }}
              />
              <circle
                cx={branchEndX}
                cy={itemY}
                r={5 * s}
                fill={accentColor}
                style={{
                  transformOrigin: `${branchEndX}px ${itemY}px`,
                  transform: `scale(${dotScale})`,
                  opacity: dotScale > 0 ? 1 : 0,
                  transition: "none",
                }}
              />
            </g>
          );
        })}
      </svg>

      {/* HTML Overlay for Typography */}
      
      {/* Guest 1 Box */}
      <div
        style={{
          position: "absolute",
          left: leftX - cardW / 2,
          top: topY - cardH / 2,
          width: cardW,
          height: cardH,
          border: `2px solid ${accentColor}`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity: guest1Opacity,
          transform: `translateY(${guest1Slide}px)`,
          fontFamily: playfairFamily,
          color: textColor,
          fontSize: 34 * s,
          fontWeight: 600,
          letterSpacing: 2 * s,
          transition: "none",
        }}
      >
        {guest1}
      </div>

      {/* Guest 2 Box */}
      <div
        style={{
          position: "absolute",
          left: rightX - cardW / 2,
          top: topY - cardH / 2,
          width: cardW,
          height: cardH,
          border: `2px solid ${accentColor}`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity: guest2Opacity,
          transform: `translateY(${guest2Slide}px)`,
          fontFamily: playfairFamily,
          color: textColor,
          fontSize: 34 * s,
          fontWeight: 600,
          letterSpacing: 2 * s,
          transition: "none",
        }}
      >
        {guest2}
      </div>

      {/* Cost Labels */}
      {costs.map((cost, i) => {
        const numItems = costs.length;
        const yStep = (listEndY - listStartY) / Math.max(1, numItems - 1);
        const itemY = listStartY + i * yStep;
        
        const progressRatio = i / Math.max(1, numItems - 1);
        const itemStemTime = f_stem + Math.floor(stem_duration * progressRatio);
        
        const isLeft = i % 2 === 0;
        const branchEndX = isLeft ? width * 0.35 : width * 0.65;
        
        const labelOpacity = interpolate(frame, [itemStemTime + Math.floor(0.1 * fps), itemStemTime + Math.floor(0.4 * fps)], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        
        const slideBase = 20 * s;
        const labelSlide = interpolate(frame, [itemStemTime + Math.floor(0.1 * fps), itemStemTime + Math.floor(0.4 * fps)], [isLeft ? slideBase : -slideBase, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.quad),
        });

        // Positioning logic based on which side the branch is on
        const sideStyle: React.CSSProperties = isLeft
          ? { right: width - branchEndX + 20 * s, justifyContent: "flex-end" }
          : { left: branchEndX + 20 * s, justifyContent: "flex-start" };

        return (
          <div
            key={`cost-label-${i}`}
            style={{
              position: "absolute",
              top: itemY - 24 * s, // Center text vertically on the line
              height: 48 * s,
              width: 320 * s, // Fixed max width for consistent wrapping if needed
              display: "flex",
              alignItems: "center",
              ...sideStyle,
              opacity: labelOpacity,
              transform: `translateX(${labelSlide}px)`,
              fontFamily: montserratFamily,
              color: textColor,
              fontSize: 26 * s,
              fontWeight: 600,
              letterSpacing: 3 * s,
              transition: "none",
            }}
          >
            {cost}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default CostCascade;